// Generates src/generated/ from 10-spec/50-interfaces/ (C001-ADR-001 item 3). Run by `npm run build`.
// Generated files are never edited by hand and are not committed.
import { mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { compile } from 'json-schema-to-typescript';
import openapiTS, { astToString } from 'openapi-typescript';

const change = readdirSync('.sdd').find((d) => /^001-/.test(d));
const dir = `.sdd/${change}/10-spec/50-interfaces`;
const out = 'src/generated';
mkdirSync(out, { recursive: true });

const banner =
  '/* Generated by scripts/generate-types.mjs from 10-spec/50-interfaces. Do not edit. */';

const schemas = [
  ['review-config.schema.json', 'review-config', 'C001-IF-004'],
  ['workspace.schema.json', 'workspace', 'C001-IF-006'],
  ['analysis-results.schema.json', 'analysis-results', 'C001-IF-008'],
  ['review-record.schema.json', 'review-record', 'C001-IF-009'],
  ['model-output.schema.json', 'model-output', 'C001-IF-011'],
];

for (const [file, name, id] of schemas) {
  const schema = JSON.parse(readFileSync(`${dir}/${file}`, 'utf8'));
  const ts = await compile(schema, name, {
    cwd: dir,
    bannerComment: `${banner}\n/* ${id} */`,
    additionalProperties: false,
    format: false,
  });
  writeFileSync(`${out}/${name}.ts`, ts);
}

const ast = await openapiTS(pathToFileURL(`${dir}/openapi.yaml`));
writeFileSync(`${out}/openapi.ts`, `${banner}\n/* C001-IF-002 */\n${astToString(ast)}`);

writeFileSync(
  `${out}/index.ts`,
  `${banner}\n` +
    schemas.map(([, name]) => `export type * as ${camel(name)} from './${name}.js';`).join('\n') +
    `\nexport type * as openapi from './openapi.js';\n`,
);
console.log(`generated ${schemas.length + 1} interface type files in ${out}`);

function camel(s) {
  return s.replace(/-(\w)/g, (_, c) => c.toUpperCase());
}
